例题:f(x)=x^3-10x^2+x+1=0    求x

用Python:

from math import pow
def f(x):
    y = pow(x,3)-(10*x*x)+x+1
    return y
def dx(x):
    y = (3*x*x)-(20*x)+1
    return y
x = 0
if dx(x) == 0:
    print(f"Rejected Initial data: Initial dx({x}) is zero.")
else:
 for i in range(1000):
    if dx(x) == 0:
            print(f"Failures: Derivative became zero at iteration {i}.")
            break
    else:
         x = x - (f(x)/dx(x))
print(x)

