 \begin{align}
\sum_{a<n \le b} f(n) & = \int_{a}^{b} f(t) \, \mathrm{d}\left \lfloor t \right \rfloor \\
& = {\color{red}\int_{a}^{b} f(t) \, \mathrm{d} t} - \int_{a}^{b} f(t) \, \mathrm{d}\left \langle t \right \rangle \\
