#include <iostream>
#include <vector>
using namespace std;

bool next_comb(vector<int>& comb, const int n, const int k) {
    int i = k - 1;
    const int e = n - k;
    do
        comb[i]++;
    while (comb[i] > e + i && i--);
    if (comb[0] > e)
        return false;
    while (++i < k)
        comb[i] = comb[i - 1] + 1;
    return true;
}

int main() {
    int n, k;
    cout << "comb(n, k):" << endl;
    cin >> n >> k;

    if (n < k || k <= 0) {
        cout << "Invalid input: n must be >= k and k must be > 0." << endl;
        return 0;
    }

    vector<int> comb(k);
    for (int i = 0; i < k; i++)
        comb[i] = i;

    do {
        for (int i = 0; i < k; i++) {
            cout << comb[i] + 1;
            if (i < k - 1) cout << ',';
        }
        cout << endl;
    } while (next_comb(comb, n, k));

    return 0;
}

